    'function base(t){var p={tipo:t,idea:idea,enviado:new Date().toISOString()},o=origin(),k;for(k in o)p[k]=o[k];return p}',
    'function save(p){try{var k="lv_respuestas_"+idea.slice(0,40),a=JSON.parse(localStorage.getItem(k)||"[]");a.push(p);localStorage.setItem(k,JSON.stringify(a))}catch(_){}}',
