    ' er.hidden=true;b.disabled=true;var lab=b.textContent;b.textContent="Guardando…";var p=base("registro");p.email=v;',
    ' post(p,function(){email=v;su.hidden=true;d.getElementById("lv-su-ok").hidden=false;var f=form.querySelector("fieldset[data-type=email]");if(f){f.hidden=true;f.querySelector("input").value=v}go(cur,0)},',
    '  function(){b.disabled=false;b.textContent=lab;er.textContent="No hemos podido guardar tu email. Revisa tu conexión e inténtalo de nuevo.";er.hidden=false})});',
