    'function nav(i,dir){i+=dir;while(i>=0&&i<steps.length&&vis(steps[i])===0)i+=dir;return i}',
    'function go(i){cur=i;var j,total=0,pos=0;for(j=0;j<steps.length;j++){steps[j].hidden=j!==i;if(vis(steps[j])>0){total++;if(j<=i)pos++}}',
    ' lab.textContent="Paso "+pos+" de "+total;bar.style.width=Math.round(pos/total*100)+"%";',
    ' var last=nav(i,1)>=steps.length;back.hidden=nav(i,-1)<0;next.hidden=last;send.hidden=!last}',
    'function val(f){var t=f.getAttribute("data-type");',
    ' if(f.hidden&&t==="email")return email;',
    ' if(t==="choice"||t==="scale"){var r=f.querySelector("input:checked");return r?r.value:""}',
    ' if(t==="multi"){var c=f.querySelectorAll("input:checked"),a=[],i;for(i=0;i<c.length;i++)a.push(c[i].value);return a.join(", ")}',
    ' var x=f.querySelector("input,textarea");return x?trim(x.value):""}',
