// ---------- semilla estable para la marca generativa ----------
function hashSeed(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
function rng(seed) { return function () { seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
/** Marca geométrica de 2×2 teselas, distinta para cada nombre. Es un marcador de posición: la persona pondrá su logo. */
function markSvg(name, c, attrs) {
  const r = rng(hashSeed(norm(name) + '|m2'));
  const pal = [c.accent, c.text, c.soft, c.accent2];
  const shapes = ['circle', 'q0', 'q1', 'q2', 'q3', 'half0', 'half1', 'half2', 'half3', 'square'];
  let out = '';
  for (let i = 0; i < 4; i++) {
    const row = Math.floor(i / 2), col = i % 2;
    const bg = pal[Math.floor(r() * 4)]; let fg, t = 0;
    do { fg = pal[Math.floor(r() * 4)]; t++; } while (fg === bg && t < 20);
    const sh = shapes[Math.floor(r() * shapes.length)];
    let g = '<g transform="translate(' + col * 100 + ' ' + row * 100 + ')"><rect width="101" height="101" fill="' + bg + '"/>';
    if (sh === 'circle') g += '<circle cx="50" cy="50" r="40" fill="' + fg + '"/>';
    else if (sh === 'square') g += '<rect x="20" y="20" width="60" height="60" rx="10" fill="' + fg + '"/>';
    else if (sh.charAt(0) === 'q') g += '<path d="M0 0H100A100 100 0 0 1 0 100Z" fill="' + fg + '" transform="rotate(' + 90 * Number(sh.charAt(1)) + ' 50 50)"/>';
    else g += '<path d="M0 100V50A50 50 0 0 1 100 50V100Z" fill="' + fg + '" transform="rotate(' + 90 * Number(sh.charAt(4)) + ' 50 50)"/>';
    out += g + '</g>';
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" ' + (attrs || '') + '>' + out + '</svg>';
}


