const FAM_ORDER = ['saas', 'shop', 'serv', 'info', 'trade', 'colab', 'local', 'crea', 'pers'];

/** Modelo de negocio (id de Compite) → modelo de landing. */
function familyOf(model) { return FAM[MODEL_FAM[model]] ? MODEL_FAM[model] : 'serv'; }

// ---------- paleta ----------
const PRESET_COLORS = [
  { n: 'Rojo', h: '#C41E3A' }, { n: 'Azul marino', h: '#1E3A8A' }, { n: 'Verde', h: '#16A34A' }, { n: 'Naranja', h: '#EA580C' },
  { n: 'Violeta', h: '#7C3AED' }, { n: 'Turquesa', h: '#0D9488' }, { n: 'Dorado', h: '#B8860B' }, { n: 'Negro', h: '#1F2937' },
];
/** Color y modo que elige la IA según el modelo y el sector (el usuario puede cambiarlos). */
function paletteFor(famId, sector, userHex, userMode) {
  const F = FAM[famId] || FAM.serv; const sec = sector || { id: 'general', color: '#7C3AED' };
  const sobrio = sec.id === 'inversion' || sec.id === 'finanzas';
  let accent = F.fixedAccent ? F.accent : (sec.color || '#7C3AED');
  let why = F.fixedAccent ? (famId === 'trade' ? 'Marino y turquesa: sobrio y tecnológico' : 'Violeta eléctrico: moderno y vibrante') : 'Color del sector ' + (sec.label || '').toLowerCase();
  if (famId === 'saas' && sec.id === 'finanzas') { accent = '#0F766E'; why = 'Turquesa sobrio para finanzas'; }
  const auto = hexToRgb(userHex) ? false : true;
  if (!auto) { accent = userHex; why = 'Color elegido por ti'; }
  const c = hexToRgb(accent); const h = rgbToHsl(c[0], c[1], c[2]);
  const accent2 = F.accent2 && F.fixedAccent && auto ? F.accent2 : hsl(h[0] + 32, Math.max(0.55, h[1]), 0.5);
  let mode = userMode && userMode !== 'auto' ? userMode : F.mode;
  if (sobrio && F.mode === 'light' && (!userMode || userMode === 'auto')) mode = 'light';
  const hue = F.hue != null && (auto || famId === 'trade') ? F.hue : h[0];
  return { accent: rgbToHex(c[0], c[1], c[2]), accent2, mode, hue, why, auto };
}
/** Juego completo de colores para un modo; todos los pares de texto pasan el contraste AA (4,5:1) y los bordes de los campos 3:1. */
function buildTokens(pal, mode, famId) {
  const F = FAM[famId] || FAM.serv; const hue = pal.hue;
  let T;
  const dark = mode === 'dark';
  const warm = F.skin === 'warm';
  const bg = dark ? hsl(hue, 0.34, 0.07) : hsl(hue, warm ? 0.55 : 0.32, warm ? 0.985 : 0.99);
  const bg2 = dark ? hsl(hue, 0.30, 0.095) : hsl(hue, warm ? 0.45 : 0.30, warm ? 0.955 : 0.965);
  const surface = dark ? hsl(hue, 0.26, 0.125) : '#FFFFFF';
  const line = dark ? hsl(hue, 0.20, 0.23) : hsl(hue, 0.22, 0.87);
  const text = dark ? hsl(hue, 0.18, 0.96) : hsl(hue, 0.30, 0.09);
  const muted = ensure(dark ? hsl(hue, 0.12, 0.72) : hsl(hue, 0.12, 0.36), [bg, bg2, surface], 4.6);
  // el texto del botón (blanco o casi negro) debe leerse sobre el color de marca; si no, se ajusta el color
  let accent = pal.accent; const on = onColor(accent);
  if (contrast(on, accent) < 4.6) accent = ensure(accent, [on], 4.6);
  const ac = hexToRgb(accent), ah = rgbToHsl(ac[0], ac[1], ac[2]);
  const soft = dark ? hsl(ah[0], Math.min(0.5, ah[1]), 0.16) : hsl(ah[0], Math.min(0.65, ah[1]), 0.945);
  const grounds = [bg, bg2, surface, soft];
  T = {
    bg, bg2, surface, line, text, muted, accent, on,
    atext: ensure(accent, grounds, 4.6), soft, atextSoft: ensure(accent, [soft], 4.6), accent2: pal.accent2,
    ring: ensure(accent, [bg, surface], 3.1),
    bd: ensure(hsl(hue, 0.10, 0.5), [bg, bg2, surface], 3.1),
    up: ensure('#16A34A', [bg, surface], 3.1), dn: ensure('#EF4444', [bg, surface], 3.1), dn2: ensure('#DC2626', [bg, bg2, surface], 4.6),
    shadow: dark ? '0 18px 50px -24px rgba(0,0,0,.7)' : '0 18px 44px -26px rgba(20,24,40,.35)',
  };
  return T;
}
/** Pares de colores que se comprueban (texto normal ≥ 4,5; elementos gráficos ≥ 3). */
function auditTokens(T, label) {
  const P = [['Texto sobre el fondo', T.text, T.bg, 4.5], ['Texto sobre tarjetas', T.text, T.surface, 4.5], ['Texto secundario sobre el fondo', T.muted, T.bg, 4.5], ['Texto secundario sobre franjas', T.muted, T.bg2, 4.5], ['Texto secundario sobre tarjetas', T.muted, T.surface, 4.5],
    ['Enlaces y etiquetas sobre el fondo', T.atext, T.bg, 4.5], ['Enlaces y etiquetas sobre tarjetas', T.atext, T.surface, 4.5], ['Etiquetas sobre el tono suave', T.atextSoft, T.soft, 4.5], ['Texto del botón', T.on, T.accent, 4.5], ['Foco del teclado', T.ring, T.bg, 3], ['Borde de los campos', T.bd, T.bg, 3], ['Borde sobre tarjetas', T.bd, T.surface, 3], ['Mensajes de error', T.dn2, T.bg, 4.5], ['Texto sobre el color de marca', T.on, T.accent, 4.5]];
  return P.map((p) => ({ k: p[0], ratio: Math.round(contrast(p[1], p[2]) * 100) / 100, min: p[3], ok: contrast(p[1], p[2]) >= p[3], mode: label }));
}


// ============================================================
// Textos por defecto (AIDA / PAS) y piezas de la página
// ============================================================
const KEYS_LABEL = { h1: 'Titular', sub: 'Subtítulo', cta: 'Botón principal', eyebrow: 'Etiqueta superior', lead: 'Frase de apoyo', micro: 'Texto bajo el formulario' };

function priceText(price) {
  if (!price || !price.v) return '';
  const per = price.per ? ({ mes: 'al mes', 'año': 'al año', hora: 'por hora', 'sesión': 'por sesión' }[price.per] || 'por ' + price.per) : '';
  return 'unos ' + NUMF.format(Math.round(price.v)) + ' €' + (per ? ' ' + per : '');
}
function surveyTime(nq) { const s = Math.max(15, Math.round(nq * 8 / 5) * 5); return s >= 90 ? 'unos ' + Math.round(s / 60) + ' minutos' : s + ' segundos'; }

/** Mapa plano clave → texto, con todo lo que se ve en la landing. */
function buildCopy(c) {
  const t = c.tone, F = c.F, S = c.sec, N = c.N, d = {};
  const Pn = c.Pn || '';
  const Pa = Pn ? withArticle(Pn) : 'una forma más sencilla de resolver un problema real';
  const noArt = (Pn || 'una forma más sencilla de resolver un problema real').replace(/^(un|una|unos|unas|el|la|los|las)\s+/i, '');
  const A = plain(c.A) || S.audience;
  // titular: cuatro variantes; la primera es la de la fórmula y el tono elegidos
  const pool = [F.h1[c.formula][t], c.formula === 'PAS' || t === 2 ? S.bold : S.hook,
    N + ': ' + capFirst(noArt),
    c.audUser ? 'Hecho para ' + lowerFirst(A) + ': ' + N : N + '. ' + F.h1[c.formula][(t + 1) % 3]];
  pool.forEach((h, i) => { if (h.length > 100) pool[i] = F.h1[c.formula][t]; });
  d.h1 = pool[((c.vH % 4) + 4) % 4];
  const sub = [copula(N, Pa) + '.', 'Con ' + N + ': ' + S.benefits[0].d.charAt(0).toLowerCase() + S.benefits[0].d.slice(1), 'Pensado para ' + lowerFirst(A) + '.'];
  d.sub = clip(sub[((c.vS % 3) + 3) % 3], 170);
  if (!/[.!?]$/.test(d.sub)) d.sub += '.';
  d.eyebrow = (F.eyebrow || GEN.eyebrow)[t];
  d.navCta = ['Apuntarme', 'Pedir acceso', 'Entrar'][t];
  d.cta = F.cta[t];
  d.micro = GEN.micro[t];
  d.okT = '¡Ya estás dentro!';
  d.okD = 'Te avisaremos en cuanto haya novedades.';
  d.okCta = 'Responder la encuesta';
  d.note = F.note || '';
  d.perk = c.perkLine || '';
  d.wait = c.waitLine || '';
  d.forLine = 'Pensado para ' + lowerFirst(A) + '.';
  // prueba social
  d.proofTitle = GEN.proofTitle[t];
  d.proofNote = 'Datos públicos de contexto, con su fuente. No son resultados de ' + N + '.';
  d.testiTitle = 'Primeras opiniones';
  d.logosTitle = 'Nos acompañan';
  // problema (PAS) y solución
  d.probTitle = GEN.probTitle[t];
  S.pains.forEach((p, i) => { d['pain.' + i] = p; });
  d.agit = F.agit;
  d.sol = 'Por eso estamos creando ' + N + '. ' + S.benefits[0].d;
  // beneficios
  d.benTitle = GEN.benTitle(N)[t];
  S.benefits.slice(0, 3).forEach((b, i) => { d['ben.' + i + '.t'] = b.t; d['ben.' + i + '.d'] = b.d; });
  // la cuarta tarjeta es propia del modelo de negocio; si repite un beneficio del sector, se usa una genérica
  const dupe = S.benefits.slice(0, 3).some((b) => norm(b.t) === norm(F.mech.t) || norm(b.d) === norm(F.mech.d));
  const mech = dupe ? { t: 'Hecho con tu opinión', d: 'Lo que respondas en la encuesta decide qué construimos primero.', i: 'heart' } : F.mech;
  d['ben.3.t'] = mech.t; d['ben.3.d'] = mech.d; d['ben.3.i'] = mech.i;
  // cómo funciona
  d.howTitle = GEN.howTitle[t];
  F.steps.forEach((s, i) => { d['step.' + i + '.t'] = s[0]; d['step.' + i + '.d'] = s[1]; });
  // encuesta
  d.surTitle = GEN.surTitle[t];
  d.surLead = 'Tus respuestas deciden si construimos ' + N + ' y cómo. Son ' + c.nq + ' preguntas, ' + surveyTime(c.nq) + '.';
  d.surHint = 'Al elegir una opción pasas a la siguiente pregunta.';
  d.thanksT = '¡Gracias!';
  d.thanksD = 'Tus respuestas nos ayudan a decidir cómo construir ' + N + '. Te avisaremos de las novedades si has dejado tu email.';
  // preguntas frecuentes
  const faq = [{ q: '¿Qué es ' + N + '?', a: capFirst(Pa) + '. Todavía estamos en fase de validación: queremos comprobar con personas reales que resuelve algo que de verdad importa antes de construirlo del todo.' },
    { q: '¿Cuánto va a costar?', a: c.price ? 'Estamos pensando en ' + priceText(c.price) + ', pero aún no es definitivo: la encuesta nos ayuda a ajustarlo a lo que de verdad te parece razonable.' : 'Aún no lo hemos decidido. Por eso en la encuesta te preguntamos qué precio te parecería razonable: tu respuesta nos ayuda a fijarlo.' },
    { q: '¿Cuándo estará disponible?', a: 'Todavía no hay fecha. Si dejas tu email, te avisaremos en cuanto haya novedades, sin spam.' }]
    .concat(F.faq({ N: N, where: c.where }))
    .concat([{ q: '¿Qué hacéis con mis datos?', a: 'Usamos tu email solo para avisarte sobre ' + N + ' y tus respuestas solo para decidir qué construir. Puedes pedirnos que los borremos cuando quieras. Tienes más detalle en la política de privacidad.' }]);
  if (S.disclaimer) faq.push({ q: '¿Sustituye el consejo de un profesional?', a: S.disclaimer });
  d['faq.n'] = String(Math.min(faq.length, 6));
  faq.slice(0, 6).forEach((f, i) => { d['faq.' + i + '.q'] = f.q; d['faq.' + i + '.a'] = f.a; });
  d.faqTitle = GEN.faqTitle[t];
  d.finalTitle = GEN.finalTitle[t];
  d.finalSub = GEN.finalSub[t];
  d.foot = N + ' es un proyecto en fase de validación: todavía no se vende ni se cobra nada.';
  d.disc = S.disclaimer || '';
  d.h1Pool = pool.join('\u0001');
  return d;
}

// ============================================================
// Maquetas del hero (HTML + CSS, sin imágenes; ilustran el concepto, no muestran resultados)
// ============================================================
function candles(seed, n) {
  const r = rng(seed); let v = 52; const out = []; let x = 0;
  const W = 260, H = 116, step = W / n;
  const rows = [];
  for (let i = 0; i < n; i++) { const o = v; const dlt = (r() - 0.46) * 16; const cl = Math.max(14, Math.min(100, o + dlt)); const hi = Math.max(o, cl) + r() * 7; const lo = Math.min(o, cl) - r() * 7; rows.push([o, cl, hi, lo]); v = cl; }
  const mn = Math.min.apply(null, rows.map((q) => q[3])), mx = Math.max.apply(null, rows.map((q) => q[2]));
  const y = (q) => (H - 8 - ((q - mn) / (mx - mn || 1)) * (H - 20)).toFixed(1);
  rows.forEach((q, i) => {
    const cx = (x + step * 0.5).toFixed(1); const up = q[1] >= q[0];
    const top = y(Math.max(q[0], q[1])), bot = y(Math.min(q[0], q[1]));
    out.push('<g class="' + (up ? 'up' : 'dn') + '"><line x1="' + cx + '" x2="' + cx + '" y1="' + y(q[2]) + '" y2="' + y(q[3]) + '"/><rect x="' + (x + step * 0.18).toFixed(1) + '" y="' + top + '" width="' + (step * 0.64).toFixed(1) + '" height="' + Math.max(2.5, bot - top).toFixed(1) + '" rx="1.5"/></g>');
    x += step;
  });
  return '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none" focusable="false">' + [20, 50, 80].map((g) => '<line class="gl" x1="0" x2="' + W + '" y1="' + g + '" y2="' + g + '"/>').join('') + out.join('') + '</svg>';
}
function bars(seed, n) {
  const r = rng(seed); let out = '';
  for (let i = 0; i < n; i++) { const h = 18 + r() * 62; out += '<rect x="' + (i * 22 + 4) + '" y="' + (90 - h).toFixed(1) + '" width="14" height="' + h.toFixed(1) + '" rx="3"/>'; }
  return '<svg viewBox="0 0 ' + (n * 22 + 4) + ' 90" preserveAspectRatio="none" focusable="false">' + out + '</svg>';
}
const SK = (w, c) => '<em class="sk w' + w + (c ? ' ' + c : '') + '"></em>';
function mockHtml(kind, N, seed) {
  const bar = '<div class="mk-bar"><i></i><i></i><i></i><span>' + esc(clip(N, 24)) + '</span></div>';
  if (kind === 'dash') {
    return '<div class="mock mk-dash">' + bar + '<div class="mk-body"><div class="mk-side"><b class="on"></b><b></b><b></b><b></b></div><div class="mk-main">' +
      '<div class="mk-kpis">' + [0, 1, 2].map(() => '<div>' + SK(50) + '<strong class="sk w70"></strong></div>').join('') + '</div>' +
      '<div class="mk-chart">' + bars(seed, 11) + '</div>' +
      '<ul class="mk-list">' + [80, 60, 70].map((w) => '<li><i class="ck"></i>' + SK(w) + '<span class="pill"></span></li>').join('') + '</ul></div></div></div>';
  }
  if (kind === 'risk') {
    return '<div class="mock mk-risk">' + bar + '<div class="mk-body"><div class="mk-chart">' + candles(seed, 22) + '</div><div class="mk-plan"><p>Plan de gestión del riesgo</p>' +
      [['Riesgo máximo por operación', 34], ['Límite de pérdida definido', 58], ['Revisión semanal', 46]].map((x) => '<div class="mk-rule"><i class="ck"></i><span>' + esc(x[0]) + '</span></div>').join('') +
      '<div class="mk-meter"><span>Exposición</span><b><i></i></b></div></div></div></div>';
  }
  if (kind === 'shop') {
    const tile = (i) => { const r = rng(seed + i * 17); const k = Math.floor(r() * 3); const art = k === 0 ? '<circle cx="50" cy="50" r="30" class="a"/><circle cx="68" cy="36" r="14" class="b"/>' : k === 1 ? '<rect x="22" y="26" width="56" height="48" rx="14" class="a"/><circle cx="64" cy="42" r="12" class="b"/>' : '<path d="M20 70C20 40 40 24 62 28c14 3 20 16 18 30-2 14-16 20-30 18-14-2-30-2-30-6z" class="a"/><circle cx="36" cy="40" r="10" class="b"/>';
      return '<div class="mk-prod"><svg viewBox="0 0 100 100" focusable="false">' + art + '</svg>' + SK(80) + '<div class="mk-price">' + SK(30, 'strong') + '<span class="pill"></span></div></div>'; };
    return '<div class="mock mk-shop">' + bar + '<div class="mk-grid">' + [0, 1, 2, 3].map(tile).join('') + '</div></div>';
  }
  if (kind === 'book') {
    const r = rng(seed); let cells = '';
    for (let i = 0; i < 28; i++) { const x = r(); cells += '<i class="' + (i === 17 ? 'sel' : x > 0.78 ? 'av' : x > 0.62 ? 'on' : '') + '"></i>'; }
    return '<div class="mock mk-book">' + bar + '<div class="mk-body"><div class="mk-cal"><div class="mk-mon">' + SK(40) + '<span><i></i><i></i></span></div><div class="mk-days">' + '<b></b>'.repeat(7) + '</div><div class="mk-cells">' + cells + '</div></div>' +
      '<div class="mk-prop"><p>Tu propuesta</p>' + [70, 55, 80].map((w) => '<div class="mk-rule"><i class="ck"></i>' + SK(w) + '</div>').join('') + '<div class="mk-cta">' + SK(40, 'on') + '</div></div></div></div>';
  }
  if (kind === 'course') {
    return '<div class="mock mk-course">' + bar + '<div class="mk-body"><div class="mk-video"><span class="play"></span><div class="mk-seek"><i></i></div></div><ul class="mk-lessons">' +
      [['done', 70], ['done', 55], ['now', 80], ['', 60]].map((x) => '<li class="' + x[0] + '"><i class="dot"></i>' + SK(x[1]) + '<span class="mk-len"></span></li>').join('') + '</ul></div></div>';
  }
  if (kind === 'match') {
    const card = (cls) => '<div class="mk-person ' + cls + '"><span class="av"></span>' + SK(70) + SK(45) + '<div class="mk-chips"><i></i><i></i><i></i></div></div>';
    return '<div class="mock mk-match">' + bar + '<div class="mk-duo">' + card('a') + '<div class="mk-link"><span></span><b></b><span></span></div>' + card('b') + '</div><div class="mk-conn">' + SK(40, 'on') + '</div></div>';
  }
  return '<div class="mock mk-brand">' + bar + '<div class="mk-hero"><div class="mk-mark"></div>' + SK(70) + SK(45) + '<div class="mk-cta">' + SK(40, 'on') + '</div></div></div>';
}

// ============================================================
// Prueba social real: cifras públicas con fuente
// ============================================================
function fmtNum(v) {
  if (typeof v === 'number') {
    if (v >= 1e6) return NUMF.format(Math.round(v / 1e5) / 10) + ' M';
    if (v >= 1000) return NUMF.format(Math.round(v));
    return NUMF.format(v);
  }
  return String(v).replace(/\./g, '.');
}
/** Elige 3 cifras publicadas del sector (con fuente) para la prueba social; marca aparte la que muestra un riesgo. */
const FACT_PICK = {
  mascotas: [['base', 0], ['base', 1], ['base', 2]], salud: [['tam'], ['base', 0], ['gr']], nutricion: [['tam'], ['gr'], ['base', 1]], eventos: [['base', 0], ['base', 1], ['base', 2]],
  viajes: [['base', 0], ['base', 2], ['base', 1]], hogar: [['base', 0], ['base', 1], ['base', 2]], tecnologia: [['base', 0], ['base', 1], ['base', 2]], emprendimiento: [['base', 0], ['base', 1]],
  finanzas: [['base', 0], ['base', 1]], educacion: [['tam'], ['gr', 0, 'Crecimiento de la facturación de la formación de empresas'], ['base', 0, 'Formación de empresas a distancia (del total)']],
  moda: [['tam'], ['base', 0], ['base', 1]], inversion: [['base', 0], ['gr']], general: [['base', 0], ['base', 1], ['base', 2]],
};
const FACT_LABEL = { tam: 'Facturación anual del sector en España', gr: 'Crecimiento del sector' };
/** Etiqueta corta y exacta de una cifra a partir de su nota: primera frase, sin paréntesis ni citas. */
function labelOf(nota, fallback) {
  const t = String(nota || '').replace(/«[^»]*»/g, '').replace(/\s*\([^)]*\)/g, '').split(/\.\s|\.$/)[0].replace(/[\s,;:]+$/, '').trim();
  return t.length >= 12 && t.length <= 96 ? t : fallback;
}
/** Aviso de alcance (solo avisos que empiezan por «No»), recortado antes de los dos puntos. */
function caveatOf(nota) {
  const s = String(nota || ''), i = s.search(/\.\s/); if (i < 0) return '';
  const r = s.slice(i + 2).replace(/\.$/, '').split(':')[0].trim();
  return /^No /.test(r) && r.length <= 110 ? r : '';
}
/** sec = LV.MKT.SEC[id]; devuelve { proof: [{v,u,y,l,n,src}], risk } */
function pickFacts(sectorId, sec) {
  const out = { proof: [], risk: null };
  if (!sec) return out;
  const get = (p) => {
    let d, l, n = '';
    if (p[0] === 'tam') { d = sec.tam; if (!d || d.t !== 'p') return null; l = labelOf(d.nota, FACT_LABEL.tam); n = caveatOf(d.nota); d = Object.assign({}, d, { src: sec.tam.src || sec.tamSrc }); }
    else if (p[0] === 'gr') { d = sec.gr; if (!d || d.t !== 'p') return null; l = labelOf(d.nota, FACT_LABEL.gr); n = caveatOf(d.nota); }
    else { const b = (sec.base || [])[p[1]]; if (!b || !b.d || b.d.t !== 'p') return null; d = b.d; l = b.l; }
    if (p[2]) l = p[2];
    const src = d.src || sec.tamSrc; if (!src || !src.u) return null;
    return { v: d.v, u: d.u || '', y: d.y || '', l: l, n: n, src: { n: src.n, u: src.u } };
  };
  (FACT_PICK[sectorId] || FACT_PICK.general).forEach((p) => { const f = get(p); if (f && !out.proof.some((x) => x.l === f.l)) out.proof.push(f); });
  if (sectorId === 'inversion') { const b = (sec.base || [])[2]; if (b && b.d && b.d.t === 'p' && b.d.src) out.risk = { v: b.d.v, u: b.d.u, y: b.d.y, l: b.l, n: b.d.nota || '', src: { n: b.d.src.n, u: b.d.src.u } }; }
  return out;
}
function factValue(f) {
  const u = f.u || '';
  const num = typeof f.v === 'number' ? fmtNum(f.v) : String(f.v).replace(/^Más de /i, '> ').replace(/^más de /i, '> ');
  if (u === '%') return num + ' %';
  if (u === 'M€') return num + ' M€';
  if (u === '€') return num + ' €';
  if (u === '€/año') return num + ' €/año';
  if (u === '×') return num;
  return num + (u ? ' ' + u : '');
}


