// ---------- especificación para el motor de landings (LandGen) ----------
const firstSentence = (t) => { const m = String(t || '').replace(/\s+/g, ' ').trim().match(/^[^.!?\n]+[.!?]?/); return m ? m[0].slice(0, 160) : ''; };
