LV.landParse = function () {
  const brief = S.compite.brief || {}; const adj = brief.adj || {};
  const src = String(brief.text || '').trim() || [S.idea.name, S.idea.pitch, S.idea.audience].filter(Boolean).join('. ');
  const mo = LV.model.engine() || adj.model || 'auto', st = adj.st || 'auto', sp = LV.model.sectorPrior(); // el modelo de negocio elegido al empezar manda sobre el detectado
  const k = src + '|' + (S.idea.sector || 'auto') + '|' + mo + '|' + st + '|' + sp;
  if (k !== pk) { try { pv = LV.intake.parse(src, { sector: S.idea.sector || 'auto', model: mo, st: st, secPrior: sp }); } catch (e) { pv = null; } pk = k; }
  return pv;
};
const factCache = {};
LV.landFacts = function (id) {
  if (!factCache[id]) { let f = { proof: [], risk: null }; try { f = LandGen.pickFacts(id, LV.MKT && LV.MKT.SEC && LV.MKT.SEC[id]); } catch (e) { /* sin datos */ } factCache[id] = f; }
  return factCache[id];
};
