const E = (v, u, y, m, nota) => ({ v: v, u: u, y: y, t: 'e', m: m, nota: nota || '' });
// cuota (% del mercado o de la base indicada en shareOf) y precio de un competidor
const qE = (v, m) => ({ v: v, t: 'e', m: m || 'Peso relativo estimado: no hay cuota publicada para esta empresa en España' });
const qP = (v, m, s) => ({ v: v, t: 'p', m: m, src: s });
const pE = (txt, x, m) => ({ txt: txt, x: x, t: 'e', m: m || 'Rango aproximado de precios públicos habituales: compruébalo en su web' });
const pP = (txt, x, s) => ({ txt: txt, x: x, t: 'p', src: s });
// competidor: id, nombre, tipo de solución, tamaño, amenaza 1-3, web, cuota, precio, especialización 0-10, debilidades, cómo aprovecharlas
