  R('mercado', rep.market.sat >= 70 ? 'Mercado muy concurrido' : 'Rivales ya consolidados',
    'Los tres mayores rivales del mapa suman ≈ ' + fn(top3, 0) + ' % ' + D.shareOf + ' y la saturación estimada es del ' + rep.market.sat + ' %. Competir de frente es la apuesta más cara.',
    'Entra por el hueco del mapa: precio ' + gap.pl + ' y personalización ' + gap.sl + '.', 100 - F.room, 'dif');
  if (F.dif < 62) R('dif', 'Ser «uno más»', 'Tu diferenciación es ' + F.dif + '/100: con lo que cuentas hoy, el cliente no tendría una razón clara para elegirte.', 'Aplica al menos dos propuestas de diferenciación.', 100 - F.dif, 'dif');
  R('captacion', 'Captar clientes cuesta caro',
    'Un cliente cuesta ≈ ' + eur(e.cac) + ' de media y deja ≈ ' + eur(e.ltv) + ' (relación ' + fn(e.ltvcac, 1) + '; lo sano es 3 o más). Solo con anuncios saldría a ≈ ' + eur(Math.round(cacAds)) + '.',
    'Apóyate en canales baratos (alianzas, comunidad, boca a boca) y sube el valor por cliente.', 100 - F.acq, 'lean');
  R('capital', 'Presupuesto justo',
    'Tu presupuesto (' + eur(rep.budget) + ') cubre el ' + pct + ' % del mínimo orientativo (' + eur(e.min) + ') y aguantaría ≈ ' + fn(Math.min(e.runway, 99), 1) + ' meses de costes fijos.',
    'Fija un tope de gasto y valida con pruebas manuales antes de construir.', rep.fixed.capital, 'lean');
  R('normativo', 'Normativa del sector', rep.sector.label + ' tiene una carga normativa de nivel ' + P.n[9] + ' sobre 3: un incumplimiento puede costar más que todo tu presupuesto.',
    'Revisa la ruta de trámites en Lanza y consulta a un profesional antes de vender.', rep.fixed.normativo, 'base');
  if (rep.me.sc.confianza <= 5) R('confianza', 'Marca nueva sin pruebas', 'Las alternativas inspiran una confianza media de ' + fn(rep.market.mkt.confianza, 1) + ' sobre 10 y tú partes de ' + rep.me.sc.confianza + '.', 'Consigue testimonios reales y una garantía simple.', (6 - rep.me.sc.confianza) * 18 + 30, 'trust');
  R('claridad', 'Idea poco definida', 'Falta concretar ' + (rep.missing[0] || 'el público, el problema o el precio') + '; sin eso la confianza del análisis es ' + rep.confidence.l.toLowerCase() + '.', 'Reescribe la idea con cliente, problema, precio y canal de llegada.', rep.fixed.claridad, 'trust');
  R('operativa', 'Operativa exigente', P.o, 'Documenta el proceso y empieza con un piloto reducido.', 100 - F.ops, 'base');
  R('sector', 'Fallo típico del sector', P.f, 'Define una regla clara y contrástala con alguien del sector antes de lanzar.', 38, 'lean');
  cand.sort((a, b) => b.score - a.score);
