  risks.forEach((r, i) => { r.id = 'r' + (i + 1); r.sev = r.score >= 65 ? 3 : r.score >= 40 ? 2 : 1; });

  const recs = rep.recs.map((r) => Object.assign({}, r, { strat: REC_STRAT[r.id] || 'lean', ms: REC_MS[r.id] || [] }));
  const STRAT = {
    dif: { t: 'Entra por el hueco, no por la puerta grande', d: 'Posiciónate donde casi no hay rivales (precio ' + gap.pl + ', personalización ' + gap.sl + ') y apóyate en tus propuestas de diferenciación.' },
    lean: { t: 'Valida barato antes de gastar', d: 'Prueba con una landing, anuncios pequeños y tus primeros clientes antes de construir.' },
    trust: { t: 'Gana confianza con pruebas visibles', d: 'Testimonios, garantía y una propuesta clara reducen el riesgo que ve el cliente.' },
    base: { t: 'Ordena lo legal y lo operativo primero', d: 'Cumple la normativa y estandariza el servicio antes de crecer.' },
  };
  const used = {}; recs.forEach((r) => { used[r.strat] = 1; });
  risks.forEach((r) => { if (!used[r.strat]) r.strat = 'lean'; });
  const strats = Object.keys(STRAT).filter((k) => used[k] && risks.some((r) => r.strat === k)).map((k) => ({ id: k, t: STRAT[k].t, d: STRAT[k].d, risks: risks.filter((r) => r.strat === k).map((r) => r.id), recs: recs.filter((r) => r.strat === k).map((r) => r.id) }));
  const stIds = strats.map((s) => s.id);
  recs.forEach((r) => { if (stIds.indexOf(r.strat) < 0) r.strat = stIds[0]; });
  strats.forEach((s) => { s.recs = recs.filter((r) => r.strat === s.id).map((r) => r.id); });
  const chain = { risks, strats, recs };

  // ---------- 4 · plan de ejecución ----------
  const phases = rep.road.map((p) => {
    const w = PH_WEEKS[p.id]; const span = w[1] - w[0] + 1; const n = p.ms.length;
    const ms = p.ms.map((m, i) => {
      const a = w[0] + Math.floor(i * span / n); const b = Math.max(a, w[0] + Math.ceil((i + 1) * span / n) - 1);
      return Object.assign({}, m, { w0: a, w1: b, eur: Math.round(p.eur / n / 10) * 10 });
    });
    return Object.assign({}, p, { w0: w[0], w1: w[1], weeks: span, ms });
  });
  const msIndex = {}; phases.forEach((p) => p.ms.forEach((m) => { m.ph = p.id; msIndex[m.id] = m; }));
  recs.forEach((r) => { const first = r.ms.map((id) => msIndex[id]).filter(Boolean).sort((a, b) => a.w0 - b.w0)[0]; r.when = first ? first : null; r.msObj = r.ms.map((id) => msIndex[id]).filter(Boolean); });
