  const srcMap = {}; const addSrc = (s, what) => { if (!s || !s.u) return; (srcMap[s.u] = srcMap[s.u] || { n: s.n, u: s.u, uses: [] }); if (what && srcMap[s.u].uses.indexOf(what) < 0) srcMap[s.u].uses.push(what); };
