    if (k === 'ramp' && st0.noRamp) return;
    const b = DR[k]; const rr = k === 'fixed' ? st0.rngFixed : k === 'invest' ? st0.rngInvest : k === 'goal' ? st0.rngGoal : null;
    c.drivers.push(Object.assign({}, b, { k, min: rr ? rr[0] : b.min, max: rr ? rr[1] : b.max, d: c.C[k] != null ? c.C[k] : b.d }));
