  if (u === '€') return eur(val, Math.abs(val) < 1 ? 3 : Math.abs(val) < 100 ? (val % 1 ? 2 : 0) : 0);
  if (u === '%') return num(val, Math.abs(val) < 10 && val % 1 ? 2 : (val % 1 ? 1 : 0)) + ' %';
  if (u === '×') return num(val, 1) + '×';
  if (u === 'h') return num(val, 1) + ' h';
