    const upo = mode === 'pack' ? (1 - v.psh / 100) + v.psh / 100 * v.pn : 1;
    const aov = mode === 'markup' ? v.cost * (1 + v.markup / 100) : mode === 'pack' ? (1 - v.psh / 100) * v.price + v.psh / 100 * v.pn * v.price * (1 - v.pd / 100) : v.price;
