      x('Expectativa por operación', num(e - comR, 2) + ' R', 'En múltiplos de lo que arriesgas (tras comisión)');
      x('Aciertos mínimos para no perder', pct((1 + comR) / (1 + v.rr) * 100, 0), 'Con tu ratio y tus comisiones');
      x('Rentabilidad anual simulada', pct(r.profit[m12] * 12 / v.capital * 100, 1), 'Sobre tu capital, tras costes fijos');
      break;
