  const rev = r.rev.slice(0, hz), pro = r.profit.slice(0, hz), cum = r.cum.slice(0, hz);
  const all = (cm ? cum : rev.concat(pro)).concat([0]); const lo = Math.min.apply(null, all), hi = Math.max.apply(null, all); const s = nice(lo, hi, 4);
  const X = (i) => L + (i + 0.5) * pw / hz; const Y = (v) => Tm + ph - (v - s.a) / (s.b - s.a) * ph;
