  const step = hz <= 12 ? (W < 420 ? 2 : 1) : (W < 420 ? 4 : 2); let xl = '';
  for (let i = 0; i < hz; i++) if ((i + 1) % step === 0 || i === 0) xl += '<text class="c-lab" x="' + r1(X(i)) + '" y="' + (H - 8) + '" text-anchor="middle">' + (i + 1) + '</text>';
  const pts = (a) => a.map((v, i) => r1(X(i)) + ',' + r1(Y(v))).join(' ');
  let body = '';
  if (cm) {
    const y0 = r1(Y(0)); body += '<polygon class="c-area" points="' + r1(X(0)) + ',' + y0 + ' ' + pts(cum) + ' ' + r1(X(hz - 1)) + ',' + y0 + '"/><polyline class="c-cum" points="' + pts(cum) + '"/>';
    if (hz <= 12) for (let i = 0; i < hz; i++) body += '<circle class="c-pdot" cx="' + r1(X(i)) + '" cy="' + r1(Y(cum[i])) + '" r="3"/>';
  } else {
    for (let i = 0; i < hz; i++) { const y0 = Y(0), y1 = Y(rev[i]); body += '<rect class="c-bar" x="' + r1(X(i) - bw / 2) + '" y="' + r1(Math.min(y0, y1)) + '" width="' + r1(bw) + '" height="' + r1(Math.max(1, Math.abs(y1 - y0))) + '" rx="2"/>'; }
    body += '<polyline class="c-pro" points="' + pts(pro) + '"/>';
    if (hz <= 12) for (let i = 0; i < hz; i++) body += '<circle class="c-pdot" cx="' + r1(X(i)) + '" cy="' + r1(Y(pro[i])) + '" r="3"/>';
  }
