  flags += flag(r.be, 'Empiezas a ganar · mes ' + r.be, 'f1', 11);
  if (r.pay && r.pay !== r.be) flags += flag(r.pay, 'Recuperas · mes ' + r.pay, 'f2', 23);
  let hits = ''; for (let i = 0; i < hz; i++) hits += '<rect class="est-hit" data-m="' + i + '" x="' + r1(L + i * pw / hz) + '" y="' + Tm + '" width="' + r1(pw / hz) + '" height="' + ph + '" aria-hidden="true"/>';
  const lbl = (cm ? 'Dinero acumulado' : 'Ingresos y beneficio por mes') + ' a ' + hz + ' meses. Mes 12: ingresos ' + F.eur(r.rev[11], 0) + ', beneficio ' + F.eur(r.profit[11], 0) + ' y acumulado ' + F.eur(r.cum[11], 0) + '.';
