  const X = (p) => r1(L + p / 100 * pw), Y = (p) => r1(Tm + ph - p / 100 * ph);
  let s = '<svg class="est-svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '" role="img" aria-label="' + esc('Mapa de posicionamiento: precio de bajo a alto en horizontal y de generalista a especializado en vertical. ' + arch.map((a) => a[0] + ': ' + (a[1] >= 50 ? 'precio alto' : 'precio bajo') + ' y ' + (a[2] >= 50 ? 'especializado' : 'generalista')).join('; ') + '. Tu oferta: ' + (user.x >= 50 ? 'precio alto' : 'precio bajo') + ' y ' + (user.y >= 50 ? 'especializada' : 'generalista') + '.') + '">';
  const q = [['00', 0, 0], ['10', 50, 0], ['01', 0, 50], ['11', 50, 50]];
  q.forEach((c) => { const g = gap && gap.cell === c[0]; s += '<rect class="c-q' + (g ? ' gap' : '') + '" x="' + X(c[1]) + '" y="' + Y(c[2] + 50) + '" width="' + r1(pw / 2) + '" height="' + r1(ph / 2) + '"/>'; });
  if (gap) { const p = gap.cell; const cx = X(p[0] === '1' ? 75 : 25), cy = Y(p[1] === '1' ? 75 : 25); s += '<text class="c-gap" x="' + cx + '" y="' + cy + '" text-anchor="middle">Hueco</text>'; }
  s += '<line class="c-axis" x1="' + L + '" x2="' + (W - Rr) + '" y1="' + (Tm + ph) + '" y2="' + (Tm + ph) + '"/><line class="c-axis" x1="' + L + '" x2="' + L + '" y1="' + Tm + '" y2="' + (Tm + ph) + '"/>';
