  s += '<text class="c-lab" transform="translate(11 ' + (Tm + ph / 2) + ') rotate(-90)" text-anchor="middle">Generalista → especializado</text>';
  arch.forEach((a) => { const x = X(a[1]), y = Y(a[2]); const left = a[1] > 58; s += '<circle class="c-arch" cx="' + x + '" cy="' + y + '" r="5.5"/><text class="c-atx" x="' + (left ? x - 9 : x + 9) + '" y="' + (y + 4) + '" text-anchor="' + (left ? 'end' : 'start') + '">' + esc(a[0]) + '</text>'; });
