  L.push('Tipo de negocio: ' + m.n + ' · Estructura de precio: ' + c.n + (c.pre ? ' · Referencia de nicho: ' + c.pre.n : ''), 'Ganas con: ' + u(c.earn) + ' · Métrica clave: ' + u(c.key), '');
