  c.drivers.filter((d) => ['fixed', 'invest', 'ramp', 'goal'].indexOf(d.k) >= 0).forEach((d) => L.push('- ' + d.l + ': ' + E.show(cl.sv[d.k], d)));
  L.push('- Mes 12: ingresos ' + F.eur(cl.r.rev[11], 0) + ' · beneficio ' + F.eur(cl.r.profit[11], 0) + ' al mes');
  L.push('- Empiezas a ganar: ' + (cl.r.be ? 'mes ' + cl.r.be : 'no en 3 años') + ' · Recuperas la inversión: ' + (v.invest <= 0 ? 'sin inversión' : cl.r.pay ? 'mes ' + cl.r.pay : 'no en 3 años'));
  const nv = E.needVol(c, v, v.goal), np = c.nobands ? null : E.needPrice(c, v, v.goal), vd = c.byKey[c.vk], pd = c.byKey[c.pk];
  if (v.goal > 0) { if (nv) L.push('- Para ganar ' + F.eur(v.goal, 0) + ' al mes necesitas: ' + vd.l.toLowerCase() + ' = ' + E.show(nv.v, vd)); if (np) L.push('- ' + minLabel(pd) + ': ' + E.show(np.v, pd)); }
  L.push('- Viabilidad orientativa: ' + chk.score + '/100 (' + chk.band.l + ')', '');
  chk.list.forEach((x) => L.push('  · ' + ({ ok: 'Bien', warn: 'Ojo', risk: 'Riesgo' }[x.lv]) + ': ' + x.t));
  L.push('', '## Precio frente al mercado');
  if (band) { L.push('- Banda: ' + CH.bf(band.lo, band) + ' a ' + CH.bf(band.hi, band) + ' (medio ' + CH.bf(band.mid, band) + ') · ' + ({ p: 'publicado', e: 'estimado', u: 'dato tuyo' }[band.t]) + '. ' + band.note); if (t) L.push('- Tu posición: ' + t.l + '. ' + t.d); }
