        set('defend', '<div class="est-def"><div><span>Precio defendible</span><b>' + CH.bf(df, band) + '</b></div><div><span>Tu precio</span><b>' + CH.bf(price, band) + '</b></div></div><p class="est-p ' + (diff > df * 0.02 ? 'warn' : 'mut') + '">' + txt + ' ' + (diff > df * 0.02 ? 'Estás un ' + F.num(diff / df * 100, 0) + ' % por encima: consigue más pruebas o baja el precio.' : 'Tu precio está dentro de lo defendible.') + ' ' + bd('e') + '</p>');
