// todo perfil hereda del neutro lo que no define (vocabulario, métricas, umbrales)
Object.keys(MP).forEach((k) => { MP[k] = Object.assign({}, BASE, MP[k]); });
const CARDS = ['saas', 'trade', 'serv', 'shop', 'info', 'otro'];
// bases que se pueden elegir dentro de «Otro / Híbrido»
const BASES = [['auto', 'Detectar según mi idea'], ['saas', 'Software / SaaS'], ['trade', 'Trading e inversión'], ['serv', 'Servicios y freelance'], ['shop', 'Producto físico'], ['info', 'Infoproductos y formación'], ['crea', 'Creador de contenido'], ['colab', 'Economía colaborativa'], ['local', 'Negocio local'], ['pers', 'Proyecto personal']];
LV.MP = MP; LV.MP_BASE = BASE;

// ---------- estado y consultas ----------
const solo = () => { const a = $('#app'); return !!(a && a.dataset.solo); };
function cur() { const m = S.mdl || {}; return m; }
function key() { const m = cur(); if (!m.id || !MP[m.id] || m.id === 'crea') return ''; return m.id === 'info' && m.sub === 'crea' ? 'crea' : m.id; }
function profile() { return MP[key()] || BASE; }
function label(k) {
  k = k || key(); const m = cur();
  if (k === 'otro') { const t = String(m.custom || '').trim(); return t ? 'Otro: ' + (t.length > 26 ? t.slice(0, 25).trim() + '…' : t) : MP.otro.b; }
  return (MP[k] || BASE).b;
}
function shortLabel(k) {
  k = k || key(); const m = cur();
  if (k === 'otro') { const t = String(m.custom || '').trim(); return t ? (t.length > 14 ? t.slice(0, 13).trim() + '…' : t) : 'Otro'; }
  return (MP[k] || BASE).s || '';
}
function engine() { const k = key(); if (!k) return ''; if (k === 'otro') { const b = cur().base; return b && b !== 'auto' ? b : ''; } return MP[k].eng; }
function sectorPrior() { return (MP[key()] || BASE).sec || ''; }
function structs() {
  const e = engine(); const VE = window.ValidEst; if (!e || !VE) return [];
  const m = VE.data.MODELS.find((x) => x.id === e); if (!m) return [];
  return m.st.map((id) => ({ id, n: VE.data.STRUCTS[id].n }));
}
function needs() { return !solo() && !key(); }
LV.mp = profile;

// ---------- aplicar el perfil activo a la app ----------
function apply() {
  const p = profile();
  Object.assign(LV.THR, BASE.thr, p.thr || {});
  document.documentElement.setAttribute('data-model', key() || 'none');
}

// ---------- insignia de la cabecera ----------
function paint() {
  const th = $('#mdl-theme'); if (th && $('#btn-theme')) th.innerHTML = $('#btn-theme').innerHTML;
  const b = $('#hd-model'); if (!b) return;
  const k = key(); b.hidden = !k;
  const mi = $('#menu-model'); if (mi) mi.hidden = !k;
  if (!k) return;
  const p = MP[k]; const nm = label(k);
  const html = '<span class="mi">' + ic(p.ic) + '</span><span class="mt"><span class="mk">Modelo activo:</span> <b class="ml">' + esc(nm) + '</b><b class="ms">' + esc(shortLabel(k)) + '</b></span>' + ic('chev', 'sm');
  if (b.dataset.k !== nm + '|' + p.ic) { b.innerHTML = html; b.dataset.k = nm + '|' + p.ic; }
  b.setAttribute('aria-label', 'Modelo activo: ' + nm + '. Pulsa para cambiarlo');
  b.title = 'Cambiar el modelo de negocio';
}

// ---------- pantalla de selección ----------
let root = null, mode = 'first', sel = '', sub = '', ready = false, busy = false;
let lastFocus = null;
let draft = { custom: '', base: 'auto' };
/** Avisa a quien escuche (el asistente) de lo que la persona está haciendo en la pantalla: pick · sub · custom · base. */
function emit(type) {
  const ev = { type: type, id: sel, sub: sub, custom: String(draft.custom || '').trim(), base: draft.base };
  LV.hooks.mdl.forEach((f) => { try { f(ev); } catch (e) { /* un oyente no debe romper la selección */ } });
}

function brandHtml() {
  const src = $('.brand .vl-logo'); let logo = '';
  if (src) { const c = src.cloneNode(true); logo = c.outerHTML; }
  return '<span class="mdl-br">' + logo + '<span class="mdl-bn">Valid<span>Lance</span></span></span>';
}
function build() {
  root = $('#mdl'); if (!root) return;
  const sg = suggestion();
  root.innerHTML =
    '<div class="mdl-top"><div class="mdl-top-in">' + brandHtml() +
    '<button class="btn ico ghost" type="button" id="mdl-theme" data-act="theme" aria-label="Cambiar entre tema claro y oscuro">' + ic('sun') + '</button></div></div>' +
    '<div class="mdl-sc" id="mdl-sc"><div class="mdl-w">' +
    '<header class="mdl-hd"><p class="mdl-kicker" id="mdl-k"></p><h1 id="mdl-t" tabindex="-1"></h1><p id="mdl-d"></p></header>' +
    '<div class="mdl-grid" role="radiogroup" aria-labelledby="mdl-t" id="mdl-cards">' +
    CARDS.map((id) => {
      const p = MP[id];
      return '<button type="button" class="mc" role="radio" aria-checked="false" tabindex="-1" data-m="' + id + '">' +
        '<span class="mc-ic" aria-hidden="true">' + ic(p.ic) + '</span>' +
        '<span class="mc-b"><b class="mc-t">' + esc(p.n) + '</b><span class="mc-d">' + esc(p.d) + '</span><span class="mc-e">Ej.: ' + esc(p.eg) + '</span></span>' +
        (sg === id ? '<span class="mc-sg">Sugerido por tu idea</span>' : '') +
        '<span class="mc-ck" aria-hidden="true">' + ic('check', 'sm') + '</span></button>';
    }).join('') + '</div>' +
    '<section class="mdl-det" id="mdl-det" aria-live="polite" aria-atomic="false"></section>' +
    '</div></div>' +
    '<footer class="mdl-ft"><div class="mdl-ft-in"><button class="btn ghost" type="button" data-act="model-cancel" id="mdl-cancel" hidden>Cancelar</button>' +
    '<span class="mdl-hint" id="mdl-hint" role="status"></span>' +
    '<button class="btn pri lg" type="button" data-act="model-go" id="mdl-go" disabled aria-describedby="mdl-hint"><span>Continuar con este modelo</span>' + ic('right', 'sm') + '</button></div></footer>';
  ready = true;
  if (window.ValidLogo) window.ValidLogo.init(root);
  paint();
}
function suggestion() {
  if (mode !== 'first') return '';
  try {
    if (!LV.landParse) return '';
    const pr = LV.landParse(); if (!pr || pr.empty || pr.model.weak) return '';
    return ({ saas: 'saas', trade: 'trade', serv: 'serv', shop: 'shop', info: 'info', crea: 'info' })[pr.model.id] || '';
  } catch (e) { return ''; }
}
function detHtml() {
  if (!sel) return '<div class="mdl-empty">' + ic('info', 'sm') + '<span>Elige la tarjeta que mejor describe tu proyecto. Podrás cambiarla cuando quieras desde la cabecera.</span></div>';
  const p = MP[sel] || BASE; const a = (sel === 'info' && sub === 'crea' ? MP.crea : p).ad;
  let extra = '';
  if (sel === 'info') {
    extra += '<div class="mdl-sub" role="radiogroup" aria-label="Qué se parece más a lo tuyo">' +
      [['', 'Infoproducto', 'Curso, ebook, plantillas, taller'], ['crea', 'Creador de contenido', 'Canal, newsletter, comunidad, podcast']].map((o) =>
        '<button type="button" role="radio" class="mdl-opt" data-act="model-sub" data-v="' + o[0] + '" aria-checked="' + (sub === o[0]) + '"><b>' + o[1] + '</b><small>' + o[2] + '</small></button>').join('') + '</div>';
  }
  if (sel === 'otro') {
    extra += '<div class="mdl-oth"><div class="field"><label class="lbl" for="mdl-custom">Descríbelo con tus palabras <span class="mut">(opcional)</span></label>' +
      '<input class="in" id="mdl-custom" maxlength="60" autocomplete="off" placeholder="Descríbelo con tus palabras" value="' + esc(draft.custom) + '"></div>' +
      '<div class="field"><label class="lbl" for="mdl-base">Se parece más a</label><select class="in" id="mdl-base">' + BASES.map((b) => '<option value="' + b[0] + '"' + (draft.base === b[0] ? ' selected' : '') + '>' + b[1] + '</option>').join('') + '</select>' +
      '<p class="help">Si no estás seguro, déjalo en detectar: lo deduciremos del texto de tu idea.</p></div></div>';
  }
  return '<div class="mdl-det-in"><div class="mdl-det-h"><span class="mc-ic" aria-hidden="true">' + ic(p.ic) + '</span><div><h2>Con «' + esc(p.b) + '» ValidLance cambia</h2><p class="mut">Se aplica a todos los módulos, y puedes cambiarlo después.</p></div></div>' +
    '<dl class="mdl-ad"><div><dt>' + ic('pen', 'sm') + 'Lenguaje</dt><dd>' + esc(a[0]) + '</dd></div><div><dt>' + ic('trend', 'sm') + 'Métricas</dt><dd>' + esc(a[1]) + '</dd></div><div><dt>' + ic('compite', 'sm') + 'Análisis</dt><dd>' + esc(a[2]) + '</dd></div></dl>' +
    extra + (p.note ? '<p class="note mdl-note">' + ic('alert', 'sm') + '<span>' + esc(p.note) + '</span></p>' : '') + '</div>';
}
function paintSel() {
  $$('.mc', root).forEach((c, i) => {
    const on = c.dataset.m === sel; c.setAttribute('aria-checked', String(on));
    c.tabIndex = on || (!sel && i === 0) ? 0 : -1; c.classList.toggle('on', on);
  });
  $('#mdl-det').innerHTML = detHtml();
  const go = $('#mdl-go'); go.disabled = !sel;
  const hint = $('#mdl-hint');
  hint.textContent = sel ? 'Elegido: ' + MP[sel].n : 'Elige una tarjeta para continuar';
  hint.classList.toggle('ok', !!sel);
}
function fill() {
  const first = mode === 'first';
  $('#mdl-k').textContent = first ? 'Antes de empezar' : 'Cambiar de modelo';
  $('#mdl-t').textContent = first ? '¿Qué tipo de negocio vas a validar?' : 'Cambia tu modelo de negocio';
  $('#mdl-d').textContent = first ? 'Elige tu modelo y ValidLance adaptará el lenguaje, las métricas, los campos y los análisis (competencia, precios, público y landings) a tu caso.' : 'Tus datos no se borran. El lenguaje y las métricas cambian al momento, y el informe de Compite se marcará como desactualizado para que lo vuelvas a calcular.';
  $('#mdl-cancel').hidden = first;
  root.classList.toggle('chg', !first);
  const k = key(); const m = cur();
  sel = first ? '' : (k === 'crea' ? 'info' : k); sub = first ? '' : (k === 'crea' ? 'crea' : '');
  draft = { custom: first ? '' : (m.custom || ''), base: first ? 'auto' : (m.base || 'auto') };
  paintSel();
}
function pick(id) {
  if (!MP[id] || sel === id) return;
  sel = id; if (id !== 'info') sub = '';
  paintSel(); emit('pick');
  if (window.innerWidth > 640) { // se asoma el principio del detalle sin esconder las tarjetas; en móvil no se mueve nada
    try { const sc = $('#mdl-sc'), dr = $('#mdl-det').getBoundingClientRect(), sr = sc.getBoundingClientRect(); const over = dr.top + 150 - sr.bottom; if (over > 0) sc.scrollBy({ top: over, behavior: reduceMotion() ? 'auto' : 'smooth' }); } catch (e) { /* sin desplazamiento */ }
  }
}
function reduceMotion() { try { return matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; } }

function lockApp(on) {
  const app = $('#app'), bn = document.querySelector('.bn');
  [app, bn].forEach((e) => { if (!e) return; if (on) e.setAttribute('inert', ''); else e.removeAttribute('inert'); });
}
function splashUp() { const s = $('#splash'); return !!(s && !s.hidden); }
function open(m) {
  if (!root) root = $('#mdl'); if (!root) return;
  if (!root.hidden && ready && !root.classList.contains('go')) return;
  mode = m || (key() ? 'change' : 'first');
  lastFocus = document.activeElement && document.activeElement !== document.body ? document.activeElement : null;
  build(); fill();
  root.classList.remove('go'); root.hidden = false; root.classList.remove('show'); void root.offsetWidth; root.classList.add('show');
  lockApp(true);
  if (splashUp()) root.setAttribute('inert', ''); else { root.removeAttribute('inert'); focusIn(); }
}
/** Al abrir: el foco va al título (nunca a una tarjeta sin elegir, para que ninguna parezca preseleccionada); si ya hay modelo, a la tarjeta activa. */
function focusIn() { const c = $('.mc.on', root) || $('#mdl-t', root); if (c) { try { c.focus({ preventScroll: true }); } catch (e) { /* sin foco */ } } }
function close(restore) {
  root.hidden = true; root.classList.remove('go', 'show');
  if (restore) { lockApp(false); }
}
function confirm() {
  if (!sel || busy || root.classList.contains('go')) return;
  const first = mode === 'first'; const prev = key();
  const custom = sel === 'otro' ? String(($('#mdl-custom') || {}).value || draft.custom || '').replace(/\s+/g, ' ').trim().slice(0, 60) : '';
  const base = sel === 'otro' ? (($('#mdl-base') || {}).value || draft.base || 'auto') : 'auto';
  S.mdl = { id: sel, sub: sel === 'info' ? sub : '', custom: custom, base: base, at: Date.now() };
  const changed = prev !== key();
  if (changed) {
    if (S.est && !S.est.touched) S.est = { ver: 1 };
    if (S.compite && S.compite.brief && S.compite.brief.adj) S.compite.brief.adj.st = 'auto';
  }
  apply(); LV.save();
  busy = true;
  const app = $('#app');
  const fast = reduceMotion();
  lockApp(false); app.classList.remove('pre');
  const target = first ? 'panel' : (S.view || 'panel');
  S.view = target; LV.go(target); paint(); // primero el trabajo pesado (dibujar el panel), después se anima: así la transición no se entrecorta
  const run = () => {
    if (!fast) { app.classList.add('enter'); setTimeout(() => app.classList.remove('enter'), 900); }
    root.classList.add('go');
    const b = $('#hd-model'); if (b && !fast) { b.classList.remove('pulse'); void b.offsetWidth; b.classList.add('pulse'); }
    LV.toast('Modelo activo: ' + label(), 'check');
    setTimeout(() => { close(false); busy = false; const t = $('#hd-title'); if (t) { t.setAttribute('tabindex', '-1'); try { t.focus({ preventScroll: true }); } catch (e) { /* sin foco */ } } }, fast ? 0 : 470);
  };
  if (fast) run(); else requestAnimationFrame(() => requestAnimationFrame(run));
}
function cancel() {
  if (mode === 'first' || !key()) return;
  root.classList.add('go'); lockApp(false);
  setTimeout(() => { close(false); const b = $('#hd-model'); try { (b && !b.hidden ? b : lastFocus || $('#hd-title')).focus({ preventScroll: true }); } catch (e) { /* sin foco */ } }, reduceMotion() ? 0 : 320);
}

// ---------- eventos del selector ----------
document.addEventListener('click', (e) => {
  if (!root || root.hidden) return;
  const c = e.target.closest && e.target.closest('.mc'); if (c && root.contains(c)) pick(c.dataset.m);
});
document.addEventListener('keydown', (e) => {
  if (!root || root.hidden) return;
  if (e.key === 'Escape' && mode === 'change') { e.preventDefault(); cancel(); return; }
  const c = e.target.closest && e.target.closest('.mc');
  if (c && ['ArrowRight', 'ArrowDown', 'ArrowLeft', 'ArrowUp', 'Home', 'End'].indexOf(e.key) >= 0) {
    e.preventDefault(); const list = $$('.mc', root); let i = list.indexOf(c);
    if (e.key === 'Home') i = 0; else if (e.key === 'End') i = list.length - 1; else i = (i + (e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1) + list.length) % list.length;
    // las flechas solo recorren las tarjetas (foco): marcar una es siempre una decisión explícita (clic, Espacio o Intro)
    list.forEach((x) => { x.tabIndex = x === list[i] ? 0 : -1; }); list[i].focus();
    return;
  }
  if (e.key === 'Enter' && e.target.id === 'mdl-custom' && sel) { e.preventDefault(); confirm(); return; }
  if (e.key === 'Tab') { // el foco se queda dentro de la pantalla mientras está abierta
    const f = $$('button:not([disabled]),input,select,[tabindex="0"]', root).filter((x) => !x.hidden && x.offsetParent !== null && (x.tabIndex >= 0));
    if (!f.length) return;
    const a = f[0], z = f[f.length - 1];
    if (e.shiftKey && document.activeElement === a) { e.preventDefault(); z.focus(); } else if (!e.shiftKey && document.activeElement === z) { e.preventDefault(); a.focus(); }
  }
});
document.addEventListener('input', (e) => { if (e.target.id === 'mdl-custom') { draft.custom = e.target.value; emit('custom'); } });
