  const end = (e) => {
    const D = MOB.drag; if (!D || (e && e.pointerId !== D.id)) return; MOB.drag = null;
    root.classList.remove('ax-drag');
    if (D.moved) { MOB.sup = performance.now() + 350; const L = limits(); MOB.side = (L.maxR - D.r) < D.r ? 'l' : 'r'; MOB.y = D.b; applyPos(); savePos(); if (typeof AX.onDrag === 'function') AX.onDrag(false); }
  };
