  validance: 'validlance', validlace: 'validlance', valilance: 'validlance', launchvalid: 'validlance', valdlance: 'validlance',
  presio: 'precio', presios: 'precios', kompetencia: 'competencia', competensia: 'competencia', competancia: 'competencia', enpezar: 'empezar', empesar: 'empezar', klientes: 'clientes',
