    const per = (after.match(/^(al mes|mensuales|mensual|\/mes|por mes|la hora|por hora|\/h\b|al ano|anuales|por proyecto|por sesion|por unidad|por pedido|por cliente|por alumno|por persona|por clase)/) || [''])[0];
