document.addEventListener('scroll', (e) => { if (!intro.on && !pres.hidden && pres.classList.contains('on') && !pres.classList.contains('leaving') && Date.now() - presAt > 1500 && !(e.target && e.target.nodeType === 1 && root.contains(e.target))) hidePres(); }, true);
