LV.ACT['agent-q'] = function (el) {
  const q = st.qr[Number(el.dataset.i)]; if (q == null) return;
  if (typeof q === 'string') ask(q); else if (q.q) ask(q.q); else run(q);
};
LV.ACT['agent-act'] = function (el) { try { run(JSON.parse(el.dataset.o || '{}')); } catch (e) { /* acción dañada */ } };

function fit() { inp.style.height = 'auto'; inp.style.height = Math.min(inp.scrollHeight, 112) + 'px'; send.disabled = !inp.value.trim(); }
inp.addEventListener('input', () => { fit(); AX.listen(1600); AX.pulse(); }); // Astro reacciona mientras la persona escribe
inp.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); form.requestSubmit ? form.requestSubmit() : form.dispatchEvent(new Event('submit', { cancelable: true })); } });
form.addEventListener('submit', (e) => { e.preventDefault(); const v = inp.value; if (!v.trim()) return; inp.value = ''; fit(); AX.pulse(); ask(v, { free: true }); });

// Esc cierra el asistente sin cerrar lo que haya debajo (por ejemplo la selección de modelo)
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && st.open && (panel.contains(document.activeElement) || document.activeElement === fab)) { e.preventDefault(); e.stopPropagation(); close(true); }
  else if (e.key === 'Tab' && st.open && isSheet() && panel.contains(document.activeElement)) { // en móvil la hoja es modal: el foco no se escapa
    const f = $$('button:not([disabled]),textarea,[tabindex="0"]', panel).filter((x) => x.offsetParent !== null && !x.hidden);
    if (!f.length) return; const a = f[0], z = f[f.length - 1];
    if (e.shiftKey && document.activeElement === a) { e.preventDefault(); z.focus(); } else if (!e.shiftKey && document.activeElement === z) { e.preventDefault(); a.focus(); }
  }
}, true);

// subárea de Compite: se detecta qué tarjeta del informe se abre
document.addEventListener('click', (e) => {
  const b = e.target.closest && e.target.closest('[data-act="fc-tog"]'); if (!b) return;
  setTimeout(() => { if (b.getAttribute('aria-expanded') === 'true') { lastCard = b.dataset.id || ''; schedCtx(); } }, 0);
});

// arrastrar hacia abajo para cerrar la hoja (móvil)
let drag = null;
function dStart(e) { if (!st.open || !isSheet() || (e.target.closest && e.target.closest('button'))) return; drag = { y: e.clientY, t: performance.now(), dy: 0, id: e.pointerId }; panel.style.transition = 'none'; try { e.currentTarget.setPointerCapture(e.pointerId); } catch (x) { /* sin captura */ } }
function dMove(e) { if (!drag || e.pointerId !== drag.id) return; drag.dy = Math.max(0, e.clientY - drag.y); panel.style.transform = 'translateY(' + drag.dy + 'px)'; }
