  $$('.ax', root).forEach((h) => AX.mount(h)); AX.assemble(); // el rostro de constelaciones se forma al terminar el splash
  const g = $('#mdl'); if (g) new MutationObserver(() => { lift(); schedCtx(); }).observe(g, { attributes: true, attributeFilter: ['hidden', 'class'] });
