// ---------- transición ----------
function release() {
  if (LV.model && LV.model.gateOpen()) return; // el panel sigue inerte hasta que se elige el modelo de negocio
  app.removeAttribute('inert'); if (bn) bn.removeAttribute('inert');
  app.classList.remove('pre');
}
function fadeOut() {
  if (faded) return; faded = true;
  root.classList.add('out'); release();
}
